/* Button selection preference; direct manipulation keeps its own gestures. */
(()=>{const modes=['both','tap','pinch'];let mode='both';try{const saved=localStorage.getItem('globiquest-control-input');if(modes.includes(saved))mode=saved}catch{}window.globiquest.controlInput=mode;window.globiquest.cycleControlInput=()=>{mode=modes[(modes.indexOf(mode)+1)%modes.length];window.globiquest.controlInput=mode;try{localStorage.setItem('globiquest-control-input',mode)}catch{}window.globiquest.renderXRNav?.(document.getElementById('nav'));if(mode==='tap'){const panel=typeof featureOpen!=='undefined'&&featureOpen?'featureWorkspace':({explore:'regions',words:'vocabulary',guide:'guideControls',music:'musicControls',lens:'toolControls'})[window.globiquest.workspace];if(panel)window.globiquest.presentTaskPanel?.(panel)}notify(({both:'Buttons: finger tap or pinch.',tap:'Buttons: finger tap. Pulling, drawing and panel grips still use pinch.',pinch:'Buttons: pinch to select.'})[mode])};})();
